import { z } from "zod";
import type { IntakeContext, OrderInput } from "./types";

function matchesEntire(pattern: RegExp, value: string): boolean {
  return pattern.exec(value)?.[0] === value;
}

const identifier = z.string().refine((value) =>
  matchesEntire(/^[A-Za-z0-9_-]{1,64}$/, value),
);

function isCalendarDate(year: number, month: number, day: number): boolean {
  if (
    !Number.isInteger(year) ||
    !Number.isInteger(month) ||
    !Number.isInteger(day) ||
    year < 2000 ||
    year > 2099 ||
    month < 1 ||
    month > 12 ||
    day < 1
  ) {
    return false;
  }
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day <= days[month - 1];
}

function isCanonicalDate(value: string): boolean {
  if (!matchesEntire(/^20\d{2}-\d{2}-\d{2}$/, value)) return false;
  const [year, month, day] = value.split("-").map(Number);
  return isCalendarDate(year, month, day);
}

function formatCalendarDate(year: number, month: number, day: number): string {
  return `${year.toString().padStart(4, "0")}-${month
    .toString()
    .padStart(2, "0")}-${day.toString().padStart(2, "0")}`;
}

function parseDecimalCents(value: string): number | undefined {
  if (!matchesEntire(/^(?:0|[1-9]\d*)(?:\.\d{1,2})?$/, value)) {
    return undefined;
  }

  const [integerPart = "", fractionPart = ""] = value.split(".");
  const normalizedFraction = fractionPart.padEnd(2, "0");
  const cents =
    BigInt(integerPart) * 100n +
    BigInt(normalizedFraction === "" ? "0" : normalizedFraction);
  if (cents < 1n || cents > 1_000_000n) {
    return undefined;
  }
  return Number(cents);
}

const versionOne = z.object({
  formatVersion: z.literal(1).optional(),
  id: identifier,
  customerId: identifier,
  amountCents: z.number().int().min(1).max(1_000_000),
  shipOn: z.string().refine(isCanonicalDate),
});

const versionSelector = z.object({
  formatVersion: z.union([z.literal(1), z.literal(2)]).optional(),
});

const decimalCents = z.string().transform((value, context) => {
  const cents = parseDecimalCents(value);
  if (cents === undefined) {
    context.addIssue({ code: "custom", message: "Invalid decimal amount" });
    return z.NEVER;
  }
  return cents;
});

const versionTwoAmount = z.object({
  decimal: decimalCents,
  currency: z.literal("USD").optional(),
});

const versionTwoDate = z
  .object({
    year: z.number().int(),
    month: z.number().int(),
    day: z.number().int(),
  })
  .refine((value) => isCalendarDate(value.year, value.month, value.day))
  .transform((value) => formatCalendarDate(value.year, value.month, value.day));

const versionTwo = z.object({
  formatVersion: z.literal(2),
  id: identifier,
  customerId: identifier,
  amount: versionTwoAmount,
  shipOn: versionTwoDate.optional(),
});

export function isOrderId(value: unknown): value is string {
  return identifier.safeParse(value).success;
}

export function parseOrder(
  value: unknown,
  context: IntakeContext,
): OrderInput | undefined {
  const selectedVersion = versionSelector.safeParse(value);
  if (!selectedVersion.success) return undefined;

  if (selectedVersion.data.formatVersion === 2) {
    const parsed = versionTwo.safeParse(value);
    if (!parsed.success) return undefined;
    return {
      id: parsed.data.id,
      customerId: parsed.data.customerId,
      amountCents: parsed.data.amount.decimal,
      shipOn: parsed.data.shipOn ?? context.receivedOn,
    };
  }

  const parsed = versionOne.safeParse(value);
  if (!parsed.success) return undefined;
  return {
    id: parsed.data.id,
    customerId: parsed.data.customerId,
    amountCents: parsed.data.amountCents,
    shipOn: parsed.data.shipOn,
  };
}
